  "slides": [
    {
      "title": "Agenda",
      "summary": "Revenue, churn, hiring progress, and the roadmap to the end of the year."
    },
    {
      "title": "Revenue",
      "summary": "3.42 million euros, 8 percent above plan. Growth driven by renewals in the mid-market segment and two enterprise expansions."
    },
    {
      "title": "Churn",
      "summary": "Logo churn 1.9 percent, best quarter this year. Two flagged accounts recovered after the reliability fixes in August."
    },
    {
      "title": "Hiring",
      "summary": "Nine of twelve planned roles closed; the three open ones are two engineers and one designer, all in final loops."
    },
    {
      "title": "Roadmap to Year End",
      "summary": "Ship the analytics beta in November, close the SOC 2 audit in December, and freeze features on December 15."
    },
    {
      "title": "Decisions Needed",
      "summary": "Approve the extra data-center budget line and confirm the January kickoff date for the analytics launch team."
    }
  ]
}
